window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a07d67d7410df43e"]={"versions": [{"id": "FIG-a07d67d7410df43e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturierte Übersichtstabelle aus der AUTOSAR-Spezifikation der E2E-Bibliothek (AUTOSAR_SWS_E2ELibrary), zugeordnet der Systemebene bzw. Basissoftware-Kommunikation. Sie definiert profilbezogene Obergrenzen für übertragbare Datenlängen im Kontext der Inter-ECU-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zweispaltige Tabelle mit den Entitäten:</p>\n<ul class=\"fig-list\"><li>Spalte 1: <code>E2E Profile</code> mit den Elementen <code>E2E Profile 1</code> und <code>E2E Profile 2</code>.\n</li><li>Spalte 2: <code>Max applicable length including control fields for inter-ECU communication</code> mit den Werten <code>30</code> für Profile 1 und <code>42</code> für Profile 2.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Spezifikationstabelle; kein dynamischer Ablauf dargestellt. Die Werte definieren Obergrenzen für die Datengröße bei der PDU-Serialisierung und E2E-Absicherung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Grenzwerte für die Konfiguration und Implementierung der E2E-Profile: Profile 1 unterstützt maximal 30 Byte und Profile 2 maximal 42 Byte Gesamtlänge inklusive Kontrollfelder (z. B. CRC und Counter). Pakete, die diese Längen überschreiten, sind mit diesen Profilen unzulässig.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-214e2e3153a689c4", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturierte Übersichtstabelle aus der AUTOSAR-Spezifikation der E2E-Bibliothek (AUTOSAR_SWS_E2ELibrary), zugeordnet der Systemebene bzw. Basissoftware-Kommunikation. Sie definiert profilbezogene Obergrenzen für übertragbare Datenlängen im Kontext der Inter-ECU-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zweispaltige Tabelle mit vorangestellter Kopfzeile:</p>\n<ul class=\"fig-list\"><li>Spalte 1: <code>E2E Profile</code> mit den Zeilen <code>E2E Profile 1</code> und <code>E2E Profile 2</code>.\n</li><li>Spalte 2: <code>Max applicable length including control fields for inter-ECU communication</code> mit den Längenwerten <code>32</code> für Profile 1 und <code>32</code> für Profile 2.\n</li><li>Oberhalb der Tabelle ist ein Textfragment („listed in the table below (see Figure 12-1).“) sichtbar.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Spezifikationstabelle; kein dynamischer Ablauf dargestellt. Die Werte definieren Obergrenzen für die Datengröße bei der PDU-Serialisierung und E2E-Absicherung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation der Maximallängen: Für <code>E2E Profile 1</code> und <code>E2E Profile 2</code> gilt jeweils eine Längenbegrenzung von 32 Byte einschließlich der Kontrollfelder für die Inter-ECU-Kommunikation.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2247da58cf49abea", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturierte Übersichtstabelle aus der AUTOSAR-Spezifikation der E2E-Bibliothek (AUTOSAR_SWS_E2ELibrary), zugeordnet der Systemebene bzw. Basissoftware-Kommunikation. Sie definiert profilbezogene Obergrenzen für übertragbare Datenlängen im Kontext der Inter-ECU-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zweispaltige Tabelle ohne explizite Spaltenüberschriften:</p>\n<ul class=\"fig-list\"><li>Spalte 1 (Profile): <code>E2E Profile 1</code>, <code>E2E Profile 2</code>, <code>E2E Profile 4</code>.\n</li><li>Spalte 2 (Längenbeschränkungen): <code>32</code> für Profile 1, <code>32</code> für Profile 2, <code>4 kB</code> für Profile 4.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Spezifikationstabelle; kein dynamischer Ablauf dargestellt. Die Werte definieren Obergrenzen für die Datengröße bei der PDU-Serialisierung und E2E-Absicherung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Obergrenzen für die E2E-Kommunikation: Profile 1 und Profile 2 sind auf 32 Byte begrenzt, während Profile 4 Nutzdaten bis zu einer Gesamtlänge von 4 kB unterstützt.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f4569521bafc81a9", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturierte Übersichtstabelle aus der AUTOSAR-Spezifikation der E2E-Bibliothek (AUTOSAR_SWS_E2ELibrary), zugeordnet der Systemebene bzw. Basissoftware-Kommunikation. Sie definiert profilbezogene Obergrenzen für übertragbare Datenlängen im Kontext der Inter-ECU-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zweispaltige Spezifikationstabelle mit Profilbezeichnungen und Längenwerten:</p>\n<ul class=\"fig-list\"><li>Zeile 1: <code>E2E Profile 1</code> – <code>32</code>\n</li><li>Zeile 2: <code>E2E Profile 2</code> – <code>32</code>\n</li><li>Zeile 3: <code>E2E Profile 4</code> – <code>4 kB</code>\n</li><li>Zeile 4: <code>E2E Profile 5</code> – <code>4 kB</code>\n</li><li>Zeile 5: <code>E2E Profile 6</code> – <code>4 kB</code>\n</li><li>Zeile 6: <code>E2E Profile 7</code> – <code>4 MB</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Spezifikationstabelle; kein dynamischer Ablauf dargestellt. Die Werte definieren Obergrenzen für die Datengröße bei der PDU-Serialisierung und E2E-Absicherung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Grenzwerte der maximal anwendbaren Längen inklusive Steuerfeldern: Profile 1 und 2 unterstützen bis zu 32 Byte; Profile 4, 5 und 6 unterstützen bis zu 4 kB; Profile 7 unterstützt Längen bis zu 4 MB.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d07dc7ae63bce9b3", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturierte Übersichtstabelle aus der AUTOSAR-Spezifikation der E2E-Bibliothek (AUTOSAR_SWS_E2ELibrary), zugeordnet der Systemebene bzw. Basissoftware-Kommunikation. Sie definiert profilbezogene Obergrenzen für übertragbare Datenlängen im Kontext der Inter-ECU-Kommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zweispaltige Spezifikationstabelle mit Profilbezeichnungen und Längenwerten:</p>\n<ul class=\"fig-list\"><li>Zeile 1: <code>E2E Profile 1</code> – <code>32</code>\n</li><li>Zeile 2: <code>E2E Profile 2</code> – <code>32</code>\n</li><li>Zeile 3: <code>E2E Profile 4</code> – <code>4kB</code>\n</li><li>Zeile 4: <code>E2E Profile 5</code> – <code>4 kB</code>\n</li><li>Zeile 5: <code>E2E Profile 6</code> – <code>4 kB</code>\n</li><li>Zeile 6: <code>E2E Profile 7</code> – <code>4 MB</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Spezifikationstabelle; kein dynamischer Ablauf dargestellt. Die Werte definieren Obergrenzen für die Datengröße bei der PDU-Serialisierung und E2E-Absicherung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Grenzwerte der maximal anwendbaren Längen inklusive Steuerfeldern: Profile 1 und 2 unterstützen bis zu 32 Byte; Profile 4, 5 und 6 unterstützen bis zu 4 kB; Profile 7 unterstützt Längen bis zu 4 MB.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a07d67d7410df43e", "to": "FIG-214e2e3153a689c4", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Tabellenwert für <code>E2E Profile 1</code>: Längenbegrenzung von <code>30</code> auf <code>32</code> geändert.\n</li><li>Tabellenwert für <code>E2E Profile 2</code>: Längenbegrenzung von <code>42</code> auf <code>32</code> geändert.\n</li><li>Über der Kopfzeile ist ein Textfragment („listed in the table below (see Figure 12-1).“) aus dem Dokumentenfließtext sichtbar.\n</li></ul>"}, {"from": "FIG-214e2e3153a689c4", "to": "FIG-2247da58cf49abea", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Tabellenkopf: Die vorangestellte Kopfzeile mit Spaltenbeschriftungen (<code>E2E Profile</code> und <code>Max applicable length including control fields for inter-ECU communication</code>) sowie das Dokumenten-Textfragment entfallen.\n</li><li>Tabelle: Zusätzlicher Tabelleneintrag für <code>E2E Profile 4</code> mit dem Maximalwert <code>4 kB</code>.\n</li></ul>"}, {"from": "FIG-2247da58cf49abea", "to": "FIG-f4569521bafc81a9", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Tabelle: Zusätzlicher Tabelleneintrag für <code>E2E Profile 5</code> mit dem Maximalwert <code>4 kB</code>.\n</li><li>Tabelle: Zusätzlicher Tabelleneintrag für <code>E2E Profile 6</code> mit dem Maximalwert <code>4 kB</code>.\n</li><li>Tabelle: Zusätzlicher Tabelleneintrag für <code>E2E Profile 7</code> mit dem Maximalwert <code>4 MB</code>.\n</li></ul>"}, {"from": "FIG-f4569521bafc81a9", "to": "FIG-d07dc7ae63bce9b3", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Tabelleneintrag <code>E2E Profile 4</code>: Leerzeichen zwischen Zahlenwert und Einheit in der Wertespalte entfernt (<code>4 kB</code> zu <code>4kB</code>).\n</li></ul>"}]};
